def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    stack = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or r == h - 1 or c == 0 or c == w - 1):
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc))
                stack.append((nr, nc))

    # Find zero regions that are enclosed by the outlines.
    enclosed = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in outside or (r, c) in enclosed:
                continue
            region = set()
            todo = [(r, c)]
            enclosed.add((r, c))
            while todo:
                y, x = todo.pop()
                region.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and (ny, nx) not in outside and (ny, nx) not in enclosed):
                        enclosed.add((ny, nx))
                        todo.append((ny, nx))

    if not enclosed:
        return [row[:] for row in grid]

    # Outline pixels connected to the boundary of an enclosed region are the
    # figures to color; unrelated open outlines remain unchanged.
    boundary_ones = set()
    for r, c in enclosed:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                boundary_ones.add((nr, nc))

    active_ones = set(boundary_ones)
    todo = list(boundary_ones)
    while todo:
        r, c = todo.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and (nr, nc) not in active_ones:
                active_ones.add((nr, nc))
                todo.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            adjacent_active = any(
                0 <= r + dr < h and 0 <= c + dc < w and (r + dr, c + dc) in active_ones
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if dr != 0 or dc != 0
            )
            if adjacent_active:
                out[r][c] = 3 if (r, c) in enclosed else 2
    return out
